def novo_id(prefix=""):
    return f"{prefix}{uuid.uuid4().hex[:12]}"


def painel_padrao(nome, link, tempo, reload_enabled=True, ativo=True, tipo="normal"):
    return {
        "id": novo_id("p_"),
        "nome": nome,
        "link": link,
        "tempo": int(tempo),
        "ativo": bool(ativo),
        "reload_enabled": bool(reload_enabled),
        "reload_strategy": "interval" if tipo == "sim" else "on_show",
        "reload_interval": 20 if tipo == "sim" else 60,
        "preserve_session": not bool(reload_enabled),
        "tipo": tipo,
        "focus_enabled": tipo == "sim",
        "focus_seconds": 20,
        "focus_zoom": 175,
        "focus_x": 87,
        "focus_y": 52,
        "focus_transition_ms": 600,
        "focus_preset": "sim_right" if tipo == "sim" else "custom",
        "iframe_mode": "auto",
    }


