def config_hash(data):
    raw = json.dumps(data, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _load_sim_persistent_state():
    try:
        if SIM_ALERT_STATE_PATH.exists():
            data = json.loads(SIM_ALERT_STATE_PATH.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return data
    except Exception:
        pass
    return {"profiles": {}}


def _save_sim_persistent_state(data):
    try:
        if not isinstance(data, dict):
            return False
        raw = json.dumps(data, ensure_ascii=False, indent=2)
        fd, temp_name = tempfile.mkstemp(prefix="sim_alert_state_", suffix=".json", dir=str(SIM_ALERT_STATE_PATH.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as tmp:
                tmp.write(raw)
                tmp.flush()
                os.fsync(tmp.fileno())
            os.replace(temp_name, SIM_ALERT_STATE_PATH)
        finally:
            if os.path.exists(temp_name):
                os.unlink(temp_name)
        return True
    except Exception:
        return False


def _sim_persistent_bucket(profile_id, ano, mes):
    state = _load_sim_persistent_state()
    profiles = state.setdefault("profiles", {})
    profile = profiles.setdefault(str(profile_id), {})
    comp_key = f"{int(ano):04d}-{int(mes):02d}"
    bucket = profile.setdefault(comp_key, {"entities": {}, "notified": [], "pending": {}, "updated_at": ""})
    if not isinstance(bucket.get("entities"), dict): bucket["entities"] = {}
    if not isinstance(bucket.get("notified"), list): bucket["notified"] = []
    if not isinstance(bucket.get("pending"), dict): bucket["pending"] = {}
    return state, bucket, comp_key


def url_valida(url):
    try:
        parsed = urlparse(str(url).strip())
        return parsed.scheme in ("http", "https") and bool(parsed.netloc)
    except Exception:
        return False


def _mascot_alert_data_uri():
    # Preferimos a versão embutida para que o mascote não dependa de arquivos
    # externos no deploy. O arquivo em assets continua aceito como fallback.
    if MASCOT_ALERT_EMBEDDED_B64:
        return f"data:image/png;base64,{MASCOT_ALERT_EMBEDDED_B64}"
    try:
        if MASCOT_ALERT_PATH.exists():
            raw = base64.b64encode(MASCOT_ALERT_PATH.read_bytes()).decode("ascii")
            return f"data:image/png;base64,{raw}"
    except Exception:
        pass
    return ""


def _mascot_sim_data_uri():
    if MASCOT_SIM_EMBEDDED_B64:
        return f"data:image/png;base64,{MASCOT_SIM_EMBEDDED_B64}"
    return ""


def _sim_alert_mascots_data():
    data = {"complete": _mascot_sim_data_uri()}
    if MASCOT_SIM_PROGRESS_EMBEDDED_B64:
        data["partial"] = f"data:image/png;base64,{MASCOT_SIM_PROGRESS_EMBEDDED_B64}"
    else:
        data["partial"] = data["complete"]
    if MASCOT_SIM_ALERT_EMBEDDED_B64:
        data["deadline"] = f"data:image/png;base64,{MASCOT_SIM_ALERT_EMBEDDED_B64}"
    else:
        data["deadline"] = data["complete"]
