def _sim_api_competencia(cfg):
    cfg = normalizar_sim_alerts(cfg)
    if cfg.get("competence_mode") == "manual":
        return int(cfg.get("manual_year") or datetime.now().year), int(cfg.get("manual_month") or 1)
    first_this_month = datetime.now().date().replace(day=1)
    previous = first_this_month - timedelta(days=1)
    return previous.year, previous.month


def _sim_api_token(base_url, credentials, force_refresh=False):
    email = credentials.get("email", "")
    senha = credentials.get("senha", "")
    cache_id = hashlib.sha256(f"{base_url}|{email}".encode("utf-8")).hexdigest()[:16]
    cache_key = f"_sim_api_token_v335_{cache_id}"
    cached = st.session_state.get(cache_key)
    now_ts = time.time()
    if not force_refresh and isinstance(cached, dict) and cached.get("token") and float(cached.get("expires_at", 0)) > now_ts + 120:
        return cached.get("token"), ""

    login_url = f"{base_url.rstrip('/')}/api/login"
    payload = json.dumps({"user": {"email": email, "password": senha}}, ensure_ascii=False).encode("utf-8")
    req = Request(login_url, data=payload, headers={
        "Content-Type": "application/json",
        "Accept": "application/json",
        "User-Agent": f"SS-Monitor/{APP_VERSION}",
    }, method="POST")
    try:
        with urlopen(req, timeout=10, context=ssl.create_default_context()) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            try:
                body = json.loads(raw) if raw else {}
            except Exception:
                body = {}
            token = str(body.get("token") or "").strip()
            auth_header = str(resp.headers.get("Authorization") or "").strip()
            if not token and auth_header.lower().startswith("bearer "):
                token = auth_header.split(" ", 1)[1].strip()
            if not token:
                return "", "Login respondeu sem token"
            st.session_state[cache_key] = {"token": token, "expires_at": now_ts + (9.5 * 3600)}
            return token, ""
    except HTTPError as exc:
        if getattr(exc, "code", None) == 401:
            return "", "Login SIM recusado (HTTP 401)"
        return "", f"Login SIM HTTP {getattr(exc, 'code', '')}".strip()
    except Exception as exc:
        return "", f"Falha no login SIM: {str(exc)[:140]}"


def _sim_server_delivered(row):
    if not isinstance(row, dict):
        return False
    if str(row.get("data_envio") or "").strip():
        return True
    value = str(row.get("status") or "").strip().lower().replace(" ", "_")
    return value in {"entregue", "no_prazo", "enviado", "confirmado", "ok", "true", "1"}

def _sim_server_municipio_name(records):
    descriptions = []
    for row in records:
        entity = row.get("monitored_entity") or {}
        desc = re.sub(r"\s+", " ", str(entity.get("descricao") or "")).strip()
        if desc:
            descriptions.append(desc)

    patterns = (
        r"PREFEITURA\s+MUNICIPAL\s+DE\s+(.+)$",
        r"C[ÂA]MARA\s+MUNICIPAL\s+DE\s+(.+)$",
        r"MUNIC[IÍ]PIO\s+DE\s+(.+)$",
        r"LEGISLATIVO\s+MUNICIPAL\s+DE\s+(.+)$",
    )
    for desc in descriptions:
        for pattern in patterns:
            match = re.search(pattern, desc, flags=re.IGNORECASE)
            if match:
                name = re.sub(r"\s+-\s+.*$", "", match.group(1)).strip()
                if name and not name.isdigit():
                    return name.title()
    return ""


def agrupar_sim_submissions_servidor(data):
    rows = []
    for row in _sim_server_rows(data):
        if not isinstance(row, dict):
            continue
        entity = row.get("monitored_entity")
        if not isinstance(entity, dict):
            continue
        # O endpoint já é consultado com monitorado=true. Ainda assim, aceitamos
        # bool, número, string e ausência do campo para evitar descartar linhas válidas.
        raw_mon = entity.get("monitorado", True)
        if isinstance(raw_mon, str):
            mon_ok = raw_mon.strip().lower() in {"true", "1", "sim", "yes", "s", "y"}
        else:
            mon_ok = bool(raw_mon)
        if not mon_ok:
            continue
        rows.append(row)
    if not rows:
        return {"states": [], "ano": None, "mes": None}

    counts = {}
    for row in rows:
        try:
            ano = int(row.get("ano"))
            mes = int(row.get("mes"))
        except Exception:
            continue
        if ano > 0 and 1 <= mes <= 12:
            counts[(ano, mes)] = counts.get((ano, mes), 0) + 1
    if not counts:
        return {"states": [], "ano": None, "mes": None}
    ano, mes = max(counts.items(), key=lambda item: item[1])[0]
    rows = [r for r in rows if str(r.get("ano")) == str(ano) and str(r.get("mes")) == str(mes)]

    groups = {}
    for row in rows:
        entity = row.get("monitored_entity") or {}
        key = str(entity.get("cod_municipio_ibge") or entity.get("cod_municipio") or "").strip()
        if key:
            groups.setdefault(key, []).append(row)

    states = []
    for key, records in groups.items():
        total = len(records)
        delivered = sum(1 for r in records if _sim_server_delivered(r))
        state = "complete" if total and delivered == total else "partial" if delivered else "pending"
        first = (records[0].get("monitored_entity") or {}) if records else {}
        municipio = _sim_server_municipio_name(records) or f"Município {first.get('cod_municipio') or key}"
        entity_states = []
        for r in records:
            ent = r.get("monitored_entity") or {}
            entity_key = str(ent.get("id") or r.get("monitored_entity_id") or r.get("id") or "").strip()
            entity_states.append({
                "key": entity_key,
                "descricao": re.sub(r"\s+", " ", str(ent.get("descricao") or ent.get("name") or "")).strip(),
                "delivered": bool(_sim_server_delivered(r)),
                "data_envio": str(r.get("data_envio") or "").strip(),
                "status": str(r.get("status") or "").strip(),
                "updated_at": str(r.get("updated_at") or "").strip(),
                "ultima_verificacao_em": str(r.get("ultima_verificacao_em") or "").strip(),
            })
        states.append({
            "key": key,
            "municipio": municipio,
            "ibge": str(first.get("cod_municipio_ibge") or "").strip(),
            "cod": str(first.get("cod_municipio") or "").strip(),
            "ano": ano,
            "mes": mes,
            "total": total,
            "delivered": delivered,
            "state": state,
            "entities": entity_states,
        })
    return {"states": states, "ano": ano, "mes": mes}


def _sim_delivery_event_key(entity_key, data_envio, status="", updated_at=""):
    entity_key = str(entity_key or "").strip()
    data_envio = str(data_envio or "").strip()
    status = str(status or "").strip()
    updated_at = str(updated_at or "").strip()
    stamp = data_envio or updated_at or status
    return f"{entity_key}|{stamp}" if entity_key and stamp else ""


def _sim_latest_confirmed_delivery(result):
    states = result.get("states") or []
    ano, mes = result.get("ano"), result.get("mes")
    latest = None
    latest_stamp = ""
    for municipality in states:
        for entity in municipality.get("entities") or []:
            if not bool(entity.get("delivered")):
                continue
            stamp = str(entity.get("updated_at") or entity.get("ultima_verificacao_em") or entity.get("data_envio") or "").strip()
            if not stamp:
                continue
            if latest is None or stamp > latest_stamp:
                latest_stamp = stamp
                latest = {
                    "municipio": municipality.get("municipio") or "Município",
                    "municipality_key": municipality.get("key"),
                    "state": municipality.get("state") or "partial",
                    "delivered": int(municipality.get("delivered") or 0),
                    "total": int(municipality.get("total") or 0),
                    "entity_key": str(entity.get("key") or ""),
                    "entity_description": str(entity.get("descricao") or "").strip(),
                    "data_envio": str(entity.get("data_envio") or "").strip(),
                    "updated_at": str(entity.get("updated_at") or "").strip(),
                    "ultima_verificacao_em": str(entity.get("ultima_verificacao_em") or "").strip(),
                    "status": str(entity.get("status") or "").strip(),
                    "ano": ano,
                    "mes": mes,
                }
    return latest


def _sim_status_norm(value):
    return str(value or "").strip().lower().replace(" ", "_")


def _sim_status_confirmado(value):
    return _sim_status_norm(value) in {"entregue", "no_prazo", "enviado", "confirmado", "ok", "true", "1"}


def _sim_rows_competencia(data, ano, mes):
    rows = []
    for row in _sim_server_rows(data):
        if not isinstance(row, dict):
            continue
        try:
            if int(row.get("ano")) != int(ano) or int(row.get("mes")) != int(mes):
                continue
        except Exception:
            continue
        ent = row.get("monitored_entity") or {}
        raw_mon = ent.get("monitorado", True)
        if isinstance(raw_mon, str):
            mon_ok = raw_mon.strip().lower() in {"true", "1", "sim", "yes", "s", "y"}
        else:
            mon_ok = bool(raw_mon)
        if not mon_ok:
            continue
        rows.append(row)
    return rows


def _sim_guess_municipio_from_description(desc):
    desc = re.sub(r"\s+", " ", str(desc or "")).strip()
    for pat in (r"PREFEITURA\s+MUNICIPAL\s+DE\s+(.+)$", r"C[ÂA]MARA\s+MUNICIPAL\s+DE\s+(.+)$", r"LEGISLATIVO\s+MUNICIPAL\s+DE\s+(.+)$"):
        m = re.search(pat, desc, flags=re.IGNORECASE)
        if m:
            name = re.sub(r"\s+-\s+.*$", "", m.group(1)).strip()
            if name and not name.isdigit():
                return name.title()
    return ""


def _sim_latest_confirmed_delivery_raw(data, ano, mes):
    """Retorna a entrega confirmada mais recente da competência.

    A API oficial pode usar códigos no campo ``status`` (ex.: ``N`` no manual)
    e, nesse formato, ``data_envio`` é a evidência mais segura. Já o endpoint
    usado pela tela costuma retornar ``entregue``/``no_prazo`` mesmo com
    ``data_envio`` nulo. Por isso reutilizamos a regra unificada
    ``_sim_server_delivered``.
    """
    latest = None
    latest_stamp = ""
    rows = _sim_rows_competencia(data, ano, mes)
    for row in rows:
        if not _sim_server_delivered(row):
            continue
        ent = row.get("monitored_entity") or {}
        stamp = str(
            row.get("data_envio")
            or row.get("updated_at")
            or row.get("ultima_verificacao_em")
            or ""
        ).strip()
        if not stamp:
            continue
        if latest is None or stamp > latest_stamp:
            latest_stamp = stamp
            desc = re.sub(r"\s+", " ", str(ent.get("descricao") or ent.get("name") or "")).strip()
            municipio = _sim_guess_municipio_from_description(desc)
            latest = {
                "alert_type": "complete",
                "title": "Nova entrega SIM confirmada",
                "municipio": municipio,
                "entity_key": str(ent.get("id") or row.get("monitored_entity_id") or row.get("id") or ""),
                "entity_description": desc,
                "entidade": desc,
                "status": str(row.get("status") or ""),
                "updated_at": str(row.get("updated_at") or ""),
                "ultima_verificacao_em": str(row.get("ultima_verificacao_em") or ""),
                "data_envio": str(row.get("data_envio") or ""),
                "event_stamp": stamp,
                "ano": int(ano),
                "mes": int(mes),
            }
    return latest


def detectar_nova_entrega_simples(data, cfg, profile_id, ano, mes):
    """Detecta somente novas entregas por entidade e emite no máximo um alerta verde.

    A primeira leitura cria o baseline. Nas leituras seguintes, qualquer entidade que
    passe de não entregue para entregue é candidata; se houver várias no mesmo ciclo,
    somente a mais recente é exibida, reproduzindo a ideia de ``Últimas Entregas``.
    """
    rows = _sim_rows_competencia(data, ano, mes)
    persistent_state, bucket, _ = _sim_persistent_bucket(profile_id, ano, mes)
    state_key = "simple_entity_delivery_v310"
    previous = bucket.get(state_key)
    if not isinstance(previous, dict):
        previous = None

    current = {}
    candidates = []
    for row in rows:
        ent = row.get("monitored_entity") or {}
        entity_key = str(ent.get("id") or row.get("monitored_entity_id") or row.get("id") or "").strip()
        if not entity_key:
            continue
        delivered = bool(_sim_server_delivered(row))
        stamp = str(row.get("data_envio") or row.get("updated_at") or row.get("ultima_verificacao_em") or "").strip()
        desc = re.sub(r"\s+", " ", str(ent.get("descricao") or ent.get("name") or "")).strip()
        current[entity_key] = {
            "delivered": delivered,
            "status": str(row.get("status") or ""),
            "stamp": stamp,
            "descricao": desc,
        }
        if previous is not None:
            old = previous.get(entity_key) or {}
            if delivered and not bool(old.get("delivered")):
                candidates.append((stamp, row))

    bucket[state_key] = current
    bucket["updated_at"] = datetime.now().isoformat()

    latest = _sim_latest_confirmed_delivery_raw(data, ano, mes)
    bucket["latest_delivery"] = latest

    alerts = []
    if previous is not None and candidates:
        candidates.sort(key=lambda x: str(x[0] or ""))
        _, row = candidates[-1]
        ent = row.get("monitored_entity") or {}
        desc = re.sub(r"\s+", " ", str(ent.get("descricao") or ent.get("name") or "")).strip()
        entity_key = str(ent.get("id") or row.get("monitored_entity_id") or row.get("id") or "").strip()
        stamp = str(row.get("data_envio") or row.get("updated_at") or row.get("ultima_verificacao_em") or "").strip()
        alert_key = f"delivery-v310|{ano}-{mes:02d}|{entity_key}|{stamp or row.get('status') or 'entregue'}"
        notified = set(bucket.get("notified_simple_v310") or [])
        if alert_key not in notified:
            municipio = _sim_guess_municipio_from_description(desc)
            alert = {
                "alert_key": alert_key,
                "alert_type": "complete",
                "title": "Nova entrega SIM confirmada",
                "municipio": municipio,
                "entity_key": entity_key,
                "entity_description": desc,
                "entidade": f"{desc} · Competência {mes:02d}/{ano}" if desc else f"Competência {mes:02d}/{ano}",
                "status": str(row.get("status") or ""),
                "data_envio": str(row.get("data_envio") or ""),
                "updated_at": str(row.get("updated_at") or ""),
                "ultima_verificacao_em": str(row.get("ultima_verificacao_em") or ""),
                "ano": int(ano),
                "mes": int(mes),
            }
            alerts.append(alert)
            notified.add(alert_key)
            bucket["notified_simple_v310"] = sorted(notified)[-3000:]
            bucket["last_event"] = {
                "detected_at": datetime.now().isoformat(),
                "entity_description": desc,
                "status": alert["status"],
                "competencia": f"{mes:02d}/{ano}",
                "alert_key": alert_key,
            }
            st.session_state[f"_sim_last_event_v310_{profile_id}"] = bucket["last_event"]

    _save_sim_persistent_state(persistent_state)
    return alerts

def detectar_nova_ultima_entrega(data, cfg, profile_id, ano, mes):
    latest = _sim_latest_confirmed_delivery_raw(data, ano, mes)
    if not latest:
        return []
    persistent_state, bucket, _ = _sim_persistent_bucket(profile_id, ano, mes)
    ref_key = "latest_confirmed_ref_v390"
    stamp = str(latest.get("updated_at") or latest.get("ultima_verificacao_em") or latest.get("data_envio") or "").strip()
    entity_key = str(latest.get("entity_key") or "").strip()
    current_ref = f"{entity_key}|{stamp}" if entity_key and stamp else ""
    previous_ref = str(bucket.get(ref_key) or "").strip()
    alerts = []
    if current_ref and previous_ref and current_ref != previous_ref:
        alert = dict(latest)
        alert["alert_key"] = f"delivery|{ano}-{mes}|{current_ref}"
        alert["alert_type"] = "complete"
        alerts.append(alert)
        bucket["last_event"] = {
            "detected_at": datetime.now().isoformat(),
            "alert_key": alert.get("alert_key"),
            "alert_type": "complete",
            "municipio": alert.get("municipio"),
            "entity_description": alert.get("entity_description"),
            "status": alert.get("status"),
            "updated_at": alert.get("updated_at"),
            "competencia": f"{int(mes):02d}/{ano}",
        }
        st.session_state[f"_sim_last_event_v390_{profile_id}"] = bucket["last_event"]
    if current_ref:
        bucket[ref_key] = current_ref
    bucket["latest_delivery"] = latest
    bucket["updated_at"] = datetime.now().isoformat()
    _save_sim_persistent_state(persistent_state)
    return alerts


def detectar_alertas_sim_servidor(result, cfg, profile_id):
    states = result.get("states") or []
    ano, mes = result.get("ano"), result.get("mes")
    if not states or not ano or not mes:
        return []

    persistent_state, bucket, comp_key = _sim_persistent_bucket(profile_id, ano, mes)
    notified = set(bucket.get("notified") or [])
    pending = bucket.get("pending") or {}
    previous_entities = bucket.get("entity_status") or {}
    baseline_exists = bool(bucket.get("status_baseline_created_at")) and isinstance(previous_entities, dict)
    now_ts = time.time()

    # Mantém alertas pendentes por 10 minutos para múltiplas tentativas de exibição.
    pending = {
        k: v for k, v in pending.items()
        if isinstance(v, dict) and now_ts - float(v.get("created_at", 0) or 0) <= 600
    }

    current_entities = {}
    entity_to_municipality = {}
    for municipality in states:
        for entity in municipality.get("entities") or []:
            entity_key = str(entity.get("key") or "").strip()
            if not entity_key:
                continue
            entity_to_municipality[entity_key] = municipality
            current_entities[entity_key] = {
                "delivered": bool(entity.get("delivered")),
                "status": str(entity.get("status") or "").strip(),
                "descricao": str(entity.get("descricao") or "").strip(),
                "data_envio": str(entity.get("data_envio") or "").strip(),
                "updated_at": str(entity.get("updated_at") or "").strip(),
                "ultima_verificacao_em": str(entity.get("ultima_verificacao_em") or "").strip(),
            }

    competencia = f"{int(mes):02d}/{ano}"

    def add_alert(municipality, entity, alert_type, transition_id=""):
        total = int(municipality.get("total") or 0)
        delivered = int(municipality.get("delivered") or 0)
        entity_key = str(entity.get("key") or "").strip()
        prefix = {"complete": "green", "partial": "orange", "deadline": "red"}.get(alert_type, alert_type)
        if alert_type == "deadline":
            alert_key = f"red|{ano}-{mes}|{municipality.get('key')}"
        else:
            stamp = transition_id or str(entity.get("updated_at") or entity.get("ultima_verificacao_em") or entity.get("status") or "")
            alert_key = f"{prefix}|{ano}-{mes}|entity:{entity_key}|{stamp}"
        if alert_key in notified:
            return False
        entity_desc = str(entity.get("descricao") or "").strip()
        if alert_type == "complete":
            resumo = f"{entity_desc} · {total} de {total} entidades entregues · Competência {competencia}" if entity_desc else f"{total} entidades entregues · Competência {competencia}"
        elif alert_type == "partial":
            resumo = f"{entity_desc} · {delivered} de {total} entidades entregues · Competência {competencia}" if entity_desc else f"{delivered} de {total} entidades entregues · Competência {competencia}"
        else:
            resumo = f"A entidade monitorada ainda não entregou · Competência {competencia}" if total == 1 else f"Nenhuma das {total} entidades monitoradas entregou · Competência {competencia}"
        alert = {
            "alert_key": alert_key,
            "alert_type": alert_type,
            "municipio": municipality.get("municipio") or "Município",
            "entidade": resumo,
            "ano": ano,
            "mes": mes,
            "delivered": delivered,
            "total": total,
            "entity_key": entity_key,
            "entity_description": entity_desc,
            "data_envio": str(entity.get("data_envio") or ""),
            "status": str(entity.get("status") or ""),
            "updated_at": str(entity.get("updated_at") or ""),
        }
        pending[alert_key] = {"created_at": now_ts, "alert": alert}
        notified.add(alert_key)
        last_event = {
            "detected_at": datetime.now().isoformat(),
            "alert_key": alert_key,
            "alert_type": alert_type,
            "municipio": alert.get("municipio"),
            "entity_description": entity_desc,
            "status": alert.get("status"),
            "updated_at": alert.get("updated_at"),
            "delivered": delivered,
            "total": total,
            "competencia": competencia,
        }
        bucket["last_event"] = last_event
        st.session_state[f"_sim_last_event_v380_{profile_id}"] = last_event
        return True

    if not baseline_exists:
        # Primeira leitura após publicação/reboot: registra o estado atual e não cria alertas antigos.
        bucket["status_baseline_created_at"] = datetime.now().isoformat()
        if bool(cfg.get("notify_initial", False)):
            for entity_key, entity in current_entities.items():
                if not entity.get("delivered"):
                    continue
                municipality = entity_to_municipality.get(entity_key) or {}
                full_entity = {**entity, "key": entity_key}
                if municipality.get("state") == "complete":
                    add_alert(municipality, full_entity, "complete", "initial")
                elif municipality.get("state") == "partial" and bool(cfg.get("partial_enabled", True)):
                    add_alert(municipality, full_entity, "partial", "initial")
    else:
        # Regra correta da API: várias entregas têm data_envio=NULL.
        # O evento é a transição de uma entidade de não entregue para um status entregue.
        for entity_key, entity in current_entities.items():
            old = previous_entities.get(entity_key) or {}
            was_delivered = bool(old.get("delivered"))
            is_delivered = bool(entity.get("delivered"))
            if not is_delivered or was_delivered:
                continue
            municipality = entity_to_municipality.get(entity_key) or {}
            full_entity = {**entity, "key": entity_key}
            transition_id = str(entity.get("updated_at") or entity.get("ultima_verificacao_em") or entity.get("status") or "entregue")
            if municipality.get("state") == "complete":
                add_alert(municipality, full_entity, "complete", transition_id)
            elif municipality.get("state") == "partial" and bool(cfg.get("partial_enabled", True)):
                add_alert(municipality, full_entity, "partial", transition_id)

    deadline_day = max(1, min(31, int(cfg.get("deadline_day", 28) or 28)))
    if bool(cfg.get("deadline_enabled", True)) and datetime.now().day >= deadline_day:
        for municipality in states:
            if municipality.get("state") != "pending":
                continue
            fake_entity = {"key": municipality.get("key"), "descricao": "", "status": "nao_entregue", "updated_at": ""}
            add_alert(municipality, fake_entity, "deadline", "")

    bucket["entity_status"] = current_entities
    bucket["notified"] = sorted(notified)[-6000:]
    bucket["pending"] = pending
    bucket["latest_delivery"] = _sim_latest_confirmed_delivery(result)
    bucket["updated_at"] = datetime.now().isoformat()
    _save_sim_persistent_state(persistent_state)

    return [
        entry.get("alert") for entry in pending.values()
        if isinstance(entry, dict) and isinstance(entry.get("alert"), dict)
    ]

def buscar_sim_submissions_servidor(panel_url, cfg):
    credentials = _sim_api_credentials()
    if not credentials.get("configured"):
        return {"ok": False, "error": "Secrets da API SIM não configurados", "data": None, "setup_required": True}
    try:
        parsed = urlparse(str(panel_url or "").strip())
        if parsed.scheme not in ("http", "https") or not parsed.netloc:
            return {"ok": False, "error": "URL do Monitor SIM inválida", "data": None}
        base_url = f"{parsed.scheme}://{parsed.netloc}"
        ano, mes = _sim_api_competencia(cfg)
        query = urlencode({"ano": ano, "mes": mes, "monitorado": "true"})
        api_url = f"{base_url}/api/sim_submissions?{query}"
        for attempt in range(2):
            token, login_error = _sim_api_token(base_url, credentials, force_refresh=attempt > 0)
            if not token:
                return {"ok": False, "error": login_error or "Não foi possível obter token SIM", "data": None}
            req = Request(api_url, headers={
                "User-Agent": f"SS-Monitor/{APP_VERSION}", "Accept": "application/json", "Cache-Control": "no-cache",
                "X-API-KEY": credentials.get("api_key", ""), "Authorization": f"Bearer {token}",
            }, method="GET")
            try:
                with urlopen(req, timeout=10, context=ssl.create_default_context()) as resp:
                    raw = resp.read()
                    try:
                        data = json.loads(raw.decode("utf-8", errors="replace"))
                    except Exception:
                        return {"ok": False, "error": "Resposta da API SIM não é JSON válido", "data": None}
                    return {"ok": True, "error": "", "data": data, "url": api_url, "ano": ano, "mes": mes, "fetched_at": datetime.now().isoformat()}
            except HTTPError as exc:
                if getattr(exc, "code", None) == 401 and attempt == 0:
                    continue
                return {"ok": False, "error": f"API SIM HTTP {getattr(exc, 'code', '')}".strip(), "data": None}
        return {"ok": False, "error": "API SIM recusou a autenticação após renovar o token", "data": None}
    except Exception as exc:
        return {"ok": False, "error": str(exc)[:180], "data": None}

def _iframe_policy_from_headers(headers, final_url=""):
    xfo = str(headers.get("X-Frame-Options", "") or "").strip()
    csp = str(headers.get("Content-Security-Policy", "") or "").strip()
    reasons = []

    if xfo:
        xfo_low = xfo.lower()
        if "deny" in xfo_low:
            reasons.append("X-Frame-Options: DENY")
        elif "sameorigin" in xfo_low:
            reasons.append("X-Frame-Options: SAMEORIGIN")
        elif "allow-from" in xfo_low and APP_EMBED_ORIGIN.lower() not in xfo_low:
            reasons.append(f"X-Frame-Options: {xfo}")

    if csp:
        directives = [d.strip() for d in csp.split(";") if d.strip()]
        frame_ancestors = next((d for d in directives if d.lower().startswith("frame-ancestors")), "")
        if frame_ancestors:
            sources = frame_ancestors.split()[1:]
            sources_low = [src.lower() for src in sources]
            app_origin = APP_EMBED_ORIGIN.lower()
            allowed = (
                "*" in sources_low
                or app_origin in sources_low
                or any(src.endswith("streamlit.app") and app_origin.endswith(src.lstrip("*.")) for src in sources_low if src.startswith("*."))
            )
            if "'none'" in sources_low or (not allowed and sources_low):
                reasons.append(f"CSP: {frame_ancestors}")

    return {
        "blocked": bool(reasons),
        "status": "blocked" if reasons else "allowed",
        "reason": " · ".join(reasons) if reasons else "Nenhum bloqueio de iframe identificado nos cabeçalhos.",
        "x_frame_options": xfo,
        "content_security_policy": csp,
        "final_url": final_url,
    }


@st.cache_data(ttl=300, show_spinner=False)
def detectar_bloqueio_iframe(url):
    """Verificação preventiva. Só marca como bloqueado quando os cabeçalhos confirmam a restrição."""
    url = str(url or "").strip()
    if not url_valida(url):
        return {"blocked": False, "status": "unknown", "reason": "URL inválida ou incompleta.", "final_url": url}

    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; S&S-Monitor/2.7; +https://monitoramentog4.streamlit.app)",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.6",
    }

    # HEAD primeiro; alguns servidores não aceitam HEAD, então fazemos GET mínimo como fallback.
    attempts = [("HEAD", None), ("GET", "bytes=0-1024")]
    last_error = ""
    for method, range_header in attempts:
        req_headers = dict(headers)
        if range_header:
            req_headers["Range"] = range_header
        req = Request(url, headers=req_headers, method=method)
        try:
            with urlopen(req, timeout=5, context=ssl.create_default_context()) as resp:
                result = _iframe_policy_from_headers(resp.headers, getattr(resp, "url", url))
                result["http_status"] = getattr(resp, "status", None)
                return result
        except HTTPError as exc:
            # Mesmo um 401/403 costuma trazer os cabeçalhos de segurança que precisamos analisar.
            result = _iframe_policy_from_headers(exc.headers or {}, getattr(exc, "url", url))
            result["http_status"] = getattr(exc, "code", None)
            if result.get("blocked"):
                return result
            last_error = f"HTTP {getattr(exc, 'code', '')}".strip()
            if method == "GET":
                result.update({"status": "unknown", "reason": f"Não foi possível confirmar a compatibilidade ({last_error})."})
                return result
        except (URLError, TimeoutError, ssl.SSLError, OSError) as exc:
            last_error = str(getattr(exc, "reason", exc))
            continue
        except Exception as exc:
            last_error = str(exc)
            continue

    return {
        "blocked": False,
        "status": "unknown",
        "reason": f"Não foi possível verificar os cabeçalhos do site: {last_error or 'sem resposta' }.",
        "final_url": url,
    }


def verificar_paineis_iframe(paineis):
    """Executa os testes automáticos em paralelo para não atrasar o início da apresentação."""
    resultados = {}
    automaticos = [p for p in paineis if p.get("iframe_mode", "auto") == "auto" and url_valida(p.get("link", ""))]
    if automaticos:
        workers = min(6, max(1, len(automaticos)))
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {executor.submit(detectar_bloqueio_iframe, p.get("link", "")): p.get("id") for p in automaticos}
            for future in as_completed(futures):
                pid = futures[future]
                try:
                    resultados[pid] = future.result()
                except Exception as exc:
                    resultados[pid] = {"blocked": False, "status": "unknown", "reason": f"Falha na verificação: {exc}"}

    for p in paineis:
        mode = p.get("iframe_mode", "auto")
        if mode == "fallback":
            resultados[p.get("id")] = {
                "blocked": True,
                "status": "manual",
                "reason": "Painel configurado para usar o aviso personalizado em vez do iframe.",
                "final_url": p.get("link", ""),
            }
        elif mode == "force_iframe":
            resultados[p.get("id")] = {
                "blocked": False,
                "status": "forced",
                "reason": "Abertura em iframe forçada pela configuração do painel.",
                "final_url": p.get("link", ""),
            }
        else:
            resultados.setdefault(p.get("id"), {"blocked": False, "status": "unknown", "reason": "Compatibilidade não confirmada."})
    return resultados


def _clamp_int(value, default, minimum, maximum):
    try:
        return max(minimum, min(maximum, int(value)))
    except Exception:
        return default


def migrar_config_legada(data):
    """Migra configuração 2.0/2.1 (perfis por nome) para o formato 2.3 (perfis por ID)."""
    if not isinstance(data, dict):
        return copy.deepcopy(DEFAULT_CONFIG)

    profiles = data.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    # Já está no formato atual se as entradas tiverem id/nome.
    if all(isinstance(v, dict) and v.get("id") and v.get("nome") for v in profiles.values()):
        return data

    old_active = data.get("active_profile")
    new_profiles = {}
    name_to_id = {}

    for old_name, old_profile in profiles.items():
        if not isinstance(old_profile, dict):
            continue
        pid = novo_id("pr_")
        name_to_id[str(old_name)] = pid
        old_sim_seconds = _clamp_int(old_profile.get("sim_refresh_seconds", 20), 20, 0, 300)
        new_panels = []
        for p in old_profile.get("paineis", []):
            if not isinstance(p, dict):
                continue
            nome = str(p.get("nome") or "Novo Painel")
            link = str(p.get("link") or "")
            old_reload = bool(p.get("recarregar", True))
            is_sim = "sim" in nome.lower() or "sim-submissions" in link.lower()
            new_panels.append(
                {
                    "id": str(p.get("id") or novo_id("p_")),
                    "nome": nome,
                    "link": link,
                    "tempo": _clamp_int(p.get("tempo", 20), 20, 5, 600),
                    "ativo": bool(p.get("ativo", True)),
                    "reload_enabled": old_reload,
                    "reload_strategy": "interval" if is_sim and old_sim_seconds > 0 else "on_show",
                    "reload_interval": old_sim_seconds if is_sim and old_sim_seconds > 0 else 60,
                    "preserve_session": not old_reload,
                    "tipo": "sim" if is_sim else "normal",
                }
            )

        new_profiles[pid] = {
            "id": pid,
            "nome": str(old_name),
            "paineis": new_panels,
            "horas_reload_geral": _clamp_int(old_profile.get("horas_reload_geral", 0), 0, 0, 24),
            "full_restart_enabled": bool(old_profile.get("full_restart_enabled", False)),
            "auto_ocultar_controles": bool(old_profile.get("auto_ocultar_controles", True)),
            "modo_tv_padrao": bool(old_profile.get("modo_tv_padrao", False)),
            "preload_seconds": 8,
            "watchdog_seconds": 90,
            "ui_scale": 100,
            "toolbar_position": "top",
            "transition_ms": 220,
            "show_clock": True,
            "show_dots": True,
            "show_status": True,
            "config_view": "compact",
        }

    if not new_profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    default_id = name_to_id.get(str(old_active)) or next(iter(new_profiles))
    return {"version": CONFIG_VERSION, "default_profile_id": default_id, "profiles": new_profiles, "ticker": normalizar_ticker(data.get("ticker")), "sim_alerts": normalizar_sim_alerts(data.get("sim_alerts"))}


def normalizar_config(data):
    data = migrar_config_legada(copy.deepcopy(data))
    if not isinstance(data, dict):
        return copy.deepcopy(DEFAULT_CONFIG)

    profiles = data.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    normalized_profiles = {}
    seen_profile_ids = set()
    for key, profile in profiles.items():
        if not isinstance(profile, dict):
            continue
        pid = str(profile.get("id") or key or novo_id("pr_"))
        if pid in seen_profile_ids:
            pid = novo_id("pr_")
        seen_profile_ids.add(pid)

        nome = str(profile.get("nome") or "Perfil")
        raw_panels = profile.get("paineis") if isinstance(profile.get("paineis"), list) else []
        panels = []
        seen_panel_ids = set()
        for p in raw_panels:
            if not isinstance(p, dict):
                continue
            panel_id = str(p.get("id") or novo_id("p_"))
            if panel_id in seen_panel_ids:
                panel_id = novo_id("p_")
            seen_panel_ids.add(panel_id)

            legacy_reload = p.get("recarregar")
            reload_enabled = bool(p.get("reload_enabled", legacy_reload if legacy_reload is not None else True))
            strategy = str(p.get("reload_strategy") or "on_show")
            if strategy not in {"on_show", "interval"}:
                strategy = "on_show"
            panel_type = str(p.get("tipo") or "normal")
            if panel_type not in {"normal", "sim", "personalizado"}:
                panel_type = "normal"
            # Perfis antigos podem ter o Monitor SIM salvo como painel normal.
            # Corrige automaticamente pela identidade do painel, sem depender do campo legado.
            if _is_sim_panel_config({"tipo": panel_type, "nome": p.get("nome"), "link": p.get("link")}):
                panel_type = "sim"

            tempo_normalizado = _clamp_int(p.get("tempo", 20), 20, 5, 600)
            max_focus_seconds = max(1, tempo_normalizado - 1)
            default_focus_seconds = min(20, max_focus_seconds)
            focus_preset = str(p.get("focus_preset") or ("sim_right" if panel_type == "sim" else "custom"))
            if focus_preset not in {"custom", "sim_right", "right", "center", "left", "top_right", "bottom_right"}:
                focus_preset = "custom"

            panels.append(
                {
                    "id": panel_id,
                    "nome": str(p.get("nome") or "Novo Painel"),
                    "link": str(p.get("link") or ""),
                    "tempo": tempo_normalizado,
                    "ativo": bool(p.get("ativo", True)),
                    "reload_enabled": reload_enabled,
                    "reload_strategy": strategy,
                    "reload_interval": _clamp_int(p.get("reload_interval", 60), 60, 5, 3600),
                    "preserve_session": bool(p.get("preserve_session", not reload_enabled)),
                    "tipo": panel_type,
                    "focus_enabled": bool(p.get("focus_enabled", panel_type == "sim")),
                    "focus_seconds": _clamp_int(p.get("focus_seconds", default_focus_seconds), default_focus_seconds, 1, max_focus_seconds),
                    "focus_zoom": _clamp_int(p.get("focus_zoom", 175), 175, 100, 300),
                    "focus_x": _clamp_int(p.get("focus_x", 87 if panel_type == "sim" else 50), 87 if panel_type == "sim" else 50, 0, 100),
                    "focus_y": _clamp_int(p.get("focus_y", 52 if panel_type == "sim" else 50), 52 if panel_type == "sim" else 50, 0, 100),
                    "focus_transition_ms": _clamp_int(p.get("focus_transition_ms", 600), 600, 0, 2000),
                    "focus_preset": focus_preset,
                    "iframe_mode": str(p.get("iframe_mode", "auto")) if str(p.get("iframe_mode", "auto")) in {"auto", "force_iframe", "fallback"} else "auto",
                }
            )

        profile_norm = {
            "id": pid,
            "nome": nome,
            "paineis": panels,
            "horas_reload_geral": _clamp_int(profile.get("horas_reload_geral", 0), 0, 0, 24),
            "full_restart_enabled": bool(profile.get("full_restart_enabled", False)),
            "auto_ocultar_controles": bool(profile.get("auto_ocultar_controles", True)),
            "modo_tv_padrao": bool(profile.get("modo_tv_padrao", False)),
            "preload_seconds": _clamp_int(profile.get("preload_seconds", 8), 8, 0, 30),
            "watchdog_seconds": _clamp_int(profile.get("watchdog_seconds", 90), 90, 30, 600),
            "ui_scale": int(profile.get("ui_scale", 100)) if int(profile.get("ui_scale", 100)) in {90, 100, 110, 125} else 100,
            "toolbar_position": str(profile.get("toolbar_position", "top")) if str(profile.get("toolbar_position", "top")) in {"top", "bottom"} else "top",
            "transition_ms": int(profile.get("transition_ms", 220)) if int(profile.get("transition_ms", 220)) in {0, 150, 220, 400} else 220,
            "show_clock": bool(profile.get("show_clock", True)),
            "show_dots": bool(profile.get("show_dots", True)),
            "show_status": bool(profile.get("show_status", True)),
            "config_view": str(profile.get("config_view", "compact")) if str(profile.get("config_view", "compact")) in {"compact", "detailed"} else "compact",
        }
        normalized_profiles[pid] = profile_norm

    if not normalized_profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    default_id = str(data.get("default_profile_id") or "")
    if default_id not in normalized_profiles:
        default_id = next(iter(normalized_profiles))

    ticker = normalizar_ticker(data.get("ticker"))
    sim_alerts = normalizar_sim_alerts(data.get("sim_alerts"))
    return {"version": CONFIG_VERSION, "default_profile_id": default_id, "profiles": normalized_profiles, "ticker": ticker, "sim_alerts": sim_alerts}


def validar_config_importada(data):
    erros = []
    avisos = []
    if not isinstance(data, dict):
        return ["O arquivo precisa conter um objeto JSON."], avisos
    profiles = data.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        erros.append("Nenhum perfil de monitoramento foi encontrado.")
        return erros, avisos

    nomes = set()
    total_panels = 0
    for key, profile in profiles.items():
        if not isinstance(profile, dict):
            erros.append(f"Perfil {key} possui formato inválido.")
            continue
        nome = str(profile.get("nome") or key).strip()
        if nome.lower() in nomes:
            avisos.append(f"Há perfis com nome repetido: {nome}.")
        nomes.add(nome.lower())
        paineis = profile.get("paineis", [])
        if not isinstance(paineis, list):
            erros.append(f"Painéis do perfil {nome} não estão em uma lista.")
            continue
        total_panels += len(paineis)
        for p in paineis:
            if not isinstance(p, dict):
                erros.append(f"Há painel inválido no perfil {nome}.")
                continue
            link = str(p.get("link") or "").strip()
            if link and not url_valida(link):
                avisos.append(f"URL aparentemente inválida em {nome}: {link[:60]}")
    if total_panels == 0:
        avisos.append("A configuração importada não possui painéis cadastrados.")

    ticker = data.get("ticker")
    if isinstance(ticker, dict):
        news = ticker.get("news") if isinstance(ticker.get("news"), list) else []
        for item in news:
            if not isinstance(item, dict):
                continue
            link = str(item.get("url") or "").strip()
            if link and not url_valida(link):
                avisos.append(f"Link de notícia aparentemente inválido: {link[:60]}")
    return erros, avisos


def carregar_config():
    if CONFIG_PATH.exists():
        try:
            with CONFIG_PATH.open("r", encoding="utf-8") as f:
                return normalizar_config(json.load(f))
        except Exception as exc:
            try:
                stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                corrupt = CONFIG_PATH.with_name(f"monitoramento_config.corrompido_{stamp}.json")
                shutil.copy2(CONFIG_PATH, corrupt)
                st.session_state["config_corrompida_backup"] = corrupt.name
            except Exception:
                pass
            st.session_state["ultimo_erro_persistencia"] = f"Falha ao ler configuração: {exc}"
    return copy.deepcopy(DEFAULT_CONFIG)


def salvar_config(config, force=False):
    """Grava apenas quando necessário, com backup e substituição atômica."""
    try:
        cfg = normalizar_config(config)
        current_hash = config_hash(cfg)
        if not force and st.session_state.get("ultimo_hash_salvo") == current_hash:
            return True

        if CONFIG_PATH.exists():
            try:
                current_disk = CONFIG_PATH.read_text(encoding="utf-8")
                disk_hash = hashlib.sha256(current_disk.encode("utf-8")).hexdigest()
                new_raw = json.dumps(cfg, ensure_ascii=False, indent=2)
                new_hash_raw = hashlib.sha256(new_raw.encode("utf-8")).hexdigest()
                if disk_hash != new_hash_raw:
                    shutil.copy2(CONFIG_PATH, BACKUP_PATH)
            except Exception:
                pass

        raw = json.dumps(cfg, ensure_ascii=False, indent=2)
        fd, temp_name = tempfile.mkstemp(prefix="monitoramento_", suffix=".json", dir=str(CONFIG_PATH.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as tmp:
                tmp.write(raw)
                tmp.flush()
                os.fsync(tmp.fileno())
            os.replace(temp_name, CONFIG_PATH)
        finally:
            if os.path.exists(temp_name):
                os.unlink(temp_name)

        st.session_state["ultimo_hash_salvo"] = current_hash
        st.session_state["ultima_gravacao"] = datetime.now().strftime("%H:%M:%S")
        st.session_state.pop("ultimo_erro_persistencia", None)
        return True
    except Exception as exc:
        st.session_state["ultimo_erro_persistencia"] = str(exc)
        return False


def regenerar_ids(perfil):
    novo = copy.deepcopy(perfil)
    novo["id"] = novo_id("pr_")
    for p in novo.get("paineis", []):
        p["id"] = novo_id("p_")
    return novo


def perfil_por_id(config, pid):
    return config["profiles"].get(pid)


def perfil_id_da_url(config):
    requested = str(st.query_params.get("perfil", "") or "")
    if requested in config["profiles"]:
        return requested
    return config.get("default_profile_id") if config.get("default_profile_id") in config["profiles"] else next(iter(config["profiles"]))


def perfil_ativos(perfil):
    return [
        p for p in perfil.get("paineis", [])
        if p.get("ativo", True) and p.get("link", "").strip() and url_valida(p.get("link", ""))
    ]


def b64_json(data):
    raw = json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return base64.b64encode(raw).decode("ascii")


